#include <utility>
#include <vector>

void sortWith(std::vector<int>& values, bool (*comesBefore)(int, int))
{
    for (std::size_t i{ 0 }; i + 1 < values.size(); ++i)
    {
        std::size_t best{ i };
        for (std::size_t j{ i + 1 }; j < values.size(); ++j)
        {
            if (comesBefore(values[j], values[best]))
            {
                best = j;
            }
        }
        std::swap(values[i], values[best]);
    }
}

unitTests:
bool ascending(int a, int b) { return a < b; }
bool descending(int a, int b) { return a > b; }
bool evensFirst(int a, int b) { if ((a % 2 == 0) != (b % 2 == 0)) return a % 2 == 0; return a < b; }
TEST("ascending") { std::vector<int> v{ 5, 3, 8, 1, 9 }; sortWith(v, ascending); CHECK_EQ(v, (std::vector<int>{ 1, 3, 5, 8, 9 })); }
TEST("descending") { std::vector<int> v{ 5, 3, 8, 1, 9 }; sortWith(v, descending); CHECK_EQ(v, (std::vector<int>{ 9, 8, 5, 3, 1 })); }
TEST("a custom rule: evens first, each group ascending") { std::vector<int> v{ 5, 2, 8, 1, 4, 3 }; sortWith(v, evensFirst); CHECK_EQ(v, (std::vector<int>{ 2, 4, 8, 1, 3, 5 })); }
TEST("empty and single") { std::vector<int> e{}; sortWith(e, ascending); CHECK(e.empty()); std::vector<int> one{ 7 }; sortWith(one, descending); CHECK_EQ(one, (std::vector<int>{ 7 })); }

